modelica_source:
model Baseline
  extends Modelica.Mechanics.Translational.Examples.Damper;
end Baseline;
model BUG001
  extends Modelica.Mechanics.Translational.Examples.Damper(mass1(m=0));
end BUG001;
model BUG003
  extends Modelica.Mechanics.Translational.Examples.Damper(mass2(m=0));
end BUG003;
model BUG007
  extends Modelica.Mechanics.Translational.Examples.Damper(mass3(m=0));
end BUG007;
model FinalBUG001
  extends Modelica.Mechanics.Translational.Examples.Damper(mass1(final m=0));
end FinalBUG001;
model FinalBUG003
  extends Modelica.Mechanics.Translational.Examples.Damper(mass2(final m=0));
end FinalBUG003;
model FinalBUG007
  extends Modelica.Mechanics.Translational.Examples.Damper(mass3(final m=0));
end FinalBUG007;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG001\n");
simulate(BUG001, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG003\n");
simulate(BUG003, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG007\n");
simulate(BUG007, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG001\n");
simulate(FinalBUG001, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG003\n");
simulate(FinalBUG003, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG007\n");
simulate(FinalBUG007, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG001\n");
system("./Baseline -override mass1.m=0 -r=BUG001_override.csv");
print("AUDIT_OVERRIDE BUG003\n");
system("./Baseline -override mass2.m=0 -r=BUG003_override.csv");
print("AUDIT_OVERRIDE BUG007\n");
system("./Baseline -override mass3.m=0 -r=BUG007_override.csv");
